def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
    paths=[GEN,NB,NB.with_suffix('.html'),PASSPORT,MAP]
    backup=OUT/'before';backup.mkdir(exist_ok=False)
    before={str(p.relative_to(ROOT.parent)):sha(p) for p in paths}
    for p in paths:shutil.copy2(p,backup/p.name)
    nb=nbformat.read(NB,as_version=4);oldcodes=[dict(c) for c in nb.cells if c.cell_type=='code']
    source=GEN.read_text('utf-8')
    anchor='Сопряжение с КТ — дополнительное условие эксперимента. Оно позволяет исследовать локальную замену при общей внешней анатомии, но сохраняет зависимость от КТ за пределами окна. Кривизна подбирается в полосе исходного геометрического поля шириной 12 мм при $0\\le d\\le180$ мм; сопротивления при этом не используются.'
    refs='Библиографические сведения и границы применимости сверены с первоисточниками 14.09.2026.'
    earlier='В сравнении обязательно участвуют прямой FEM и существующая библиотека полной КТ-модели после FEM-подготовки.'
    bridge=' Дополнительные варианты М3-H и М4-H из раздела 3.4 проверяют замену наружной КТ-границы полупространством; контроль М3-Hκ отделяет эту замену от отказа от общего изгиба.'
    edits=[(anchor,anchor+'\n\n'+SECTION),(refs,REFERENCE+'\n\n'+refs),(earlier,earlier+bridge)]
    for old,new in edits:
        assert source.count(old)==1
        source=source.replace(old,new.replace('\n','\n    '))
        cells=[c for c in nb.cells if c.cell_type=='markdown' and old in c.source];assert len(cells)==1
        cells[0].source=cells[0].source.replace(old,new)
    ast.parse(source);GEN.write_text(source,encoding='utf-8')
    nb.metadata['documentation_revision']={'date':'2026-09-14','scope':'additional_halfspace_models_and_boundary_conditions','cells_reexecuted':False,'generator_sha256':sha(GEN),'previous_notebook_sha256':before[str(NB.relative_to(ROOT.parent))]}
    nbformat.validate(nb);assert oldcodes==[dict(c) for c in nb.cells if c.cell_type=='code']
    nbformat.write(nb,NB)
    passport=PASSPORT.read_text('utf-8')
    PASSPORT.write_text(passport.replace('## Статус и следующий этап',SUMMARY+'## Статус и следующий этап'),encoding='utf-8')
    m=MAP.read_text('utf-8')
    old='Научные основания и ссылки — в разделах 12.1–12.2.'
    new=old+' В разделе 3.4 добавлены ещё не рассчитанные М3-H и М4-H: криволинейное включение в полупространстве с плоской кожей; постоянное сечение и общий изгиб разделены контрольным вариантом.'
    assert m.count(old)==1;MAP.write_text(m.replace(old,new),encoding='utf-8')
    exp=HTMLExporter();exp.exclude_input=True;exp.exclude_input_prompt=True;exp.exclude_output_prompt=True
    html,_=exp.from_notebook_node(nb);NB.with_suffix('.html').write_text(html,encoding='utf-8')
    soup=BeautifulSoup(html,'html.parser')
    assert not soup.select('.jp-CodeCell .jp-InputArea, .code_cell .input_area')
    oldhtml=BeautifulSoup((backup/NB.with_suffix('.html').name).read_text('utf-8'),'html.parser')
    assert [x.get('src') for x in soup.find_all('img')]==[x.get('src') for x in oldhtml.find_all('img')]
    literals=[textwrap.dedent(n.args[0].value).strip() for n in ast.walk(ast.parse(source)) if isinstance(n,ast.Call) and isinstance(n.func,ast.Name) and n.func.id=='md' and n.args and isinstance(n.args[0],ast.Constant) and isinstance(n.args[0].value,str)]
    assert any(SECTION in s for s in literals)
    assert any(SECTION in c.source for c in nb.cells if c.cell_type=='markdown')
    (OUT/'new_text.md').write_text(SECTION+'\n\n'+REFERENCE+'\n',encoding='utf-8')
    pieces=[]
    for i,c in enumerate(nb.cells):
        if c.cell_type=='markdown':pieces.append(f'CELL {i}\n'+c.source)
        else:
            for o in c.get('outputs',[]):
                if o.get('output_type')=='stream':pieces.append(o.get('text',''))
                elif 'text/html' in o.get('data',{}):pieces.append(BeautifulSoup(o.data['text/html'],'html.parser').get_text(' ',strip=True))
                elif 'text/plain' in o.get('data',{}):pieces.append(o.data['text/plain'])
    (OUT/'reader_full_review.txt').write_text('\n\n'.join(pieces)+'\n',encoding='utf-8')
    report=dict(before=before,after={str(p.relative_to(ROOT.parent)):sha(p) for p in paths},code_cells_unchanged=True,saved_outputs_unchanged=True,code_cells=len(oldcodes),new_impedance_calculations=False,notebook_schema_valid=True,generator_matches_notebook=True,html_excludes_code=True,images_unchanged=True,reader_sha256=sha(OUT/'reader_full_review.txt'),language_status='pending_final_review')
    (OUT/'verification.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print(json.dumps({k:v for k,v in report.items() if k not in ['before','after']},ensure_ascii=False))
    print('Reader lines',len((OUT/'reader_full_review.txt').read_text('utf-8').splitlines()))
if __name__=='__main__':main()

